head.script:
// 담당 범위
//  _1 : 기본 동작 - sortLabel(미설정/true/false) x inputType(select/autoComplete, 대조 text) x Column 정렬 가능 여부(sortable true/false), 아이템 없는 Cell 값 포함
//  _2 : DataList sort() / multisort() 정렬, LinkedDataList 바인딩 (본 샘플)
//  _3 : inputType="custom"
//  - Body 전용 속성이므로 Body Column 에만 설정 (설정 영역 옵션 / "Body Column 에서만 동작" 항목 제외)
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > sortLabel]<br/>Header Column 을 클릭하여 정렬할 때 Cell 값 대신 아이템의 Label 을 기준으로 정렬할지 설정합니다.",
    "validation" : [
        "DataList 의 sort(), multisort() 메소드로 정렬할 때는 sortLabel 속성이 적용되지 않습니다.",
        "GridView 가 LinkedDataList 에 바인딩된 경우 sortLabel 속성은 적용되지 않으며 Cell 값을 기준으로 정렬됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (바인딩 = DataList, inputType = select)
    con_bindType.setValue("dataList");
    con_inputType.setValue("select");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 부서 아이템 : value 오름차순(D01 -> D04)과 Label 오름차순(개발팀 -> 회계팀)이 서로 반대가 되도록 구성
scwin.deptItems = [
    { "label" : "회계팀", "code" : "D01" },
    { "label" : "영업팀", "code" : "D02" },
    { "label" : "마케팅팀", "code" : "D03" },
    { "label" : "개발팀", "code" : "D04" }
];

// 사원별 부서 코드 (D99 는 아이템 목록에 없는 Cell 값)
//  - Cell 값 오름차순  : D01, D02, D03, D04, D99
//  - Label 오름차순    : D99(Cell 값 사용), 개발팀, 마케팅팀, 영업팀, 회계팀
scwin.rowData = [
    { "name" : "김민수", "dept" : "D02" },
    { "name" : "이서연", "dept" : "D04" },
    { "name" : "박지훈", "dept" : "D99" },
    { "name" : "최유진", "dept" : "D01" },
    { "name" : "정하늘", "dept" : "D03" }
];



// GridView 에 바인딩된 데이터 컴포넌트 (DataList 또는 LinkedDataList)
scwin.getBindComp = function () {
    return (typeof lnk_bind !== 'undefined' && lnk_bind) ? lnk_bind : dlt_bind;
}



// comp 생성
//  - GridView sortable="true", sortEvent="onclick" 고정 (Header 단일 클릭 정렬)
//  - 부서 Body Column 은 sortLabel="true" 고정 (sortLabel 이 적용되지 않는 조건을 확인하는 샘플)
//  - selectedData="false" 고정 : 기본값(true)이면 BindItemSet 아이템 목록에 없는 값(D99)이 '' 로 바뀌므로 Cell 값을 그대로 유지한다.
//  - 바인딩 = LinkedDataList 이면 dlt_bind 를 bind 하는 lnk_bind 를 만들어 GridView 에 바인딩
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof lnk_bind !== 'undefined' && lnk_bind) {
        $p.data.remove("lnk_bind");
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_dept !== 'undefined' && dlt_dept) {
        $p.data.remove("dlt_dept");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 부서 Column : sortLabel=true, selectedData=false 고정 / 아이템(BindItemSet) D01=회계팀, D02=영업팀, D03=마케팅팀, D04=개발팀 / D99 는 목록에 없는 값\n[절차] 조건 선택 -> Target 재생성 -> 부서 Header 클릭, 또는 sort / multisort 버튼(GridView 에 바인딩된 DataList / LinkedDataList 에 부서 오름차순 실행) -> 정렬 상태 확인\n[확인] Cell 값 기준이면 D01 -> D99 순, Label 기준이면 D99 -> 개발팀 -> 회계팀 순"', '', 'label1');

    // 조건 설정
    let cBindType = con_bindType.getValue();
    let cInputType = con_inputType.getValue();

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 아이템 DataList (BindItemSet 용)
    let strCode = '';
    strCode += '<w2:dataList ' + strNameSpace + ' id="dlt_dept" baseNode="list" repeatNode="map">';
    strCode += '<w2:columnInfo>';
    strCode += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strCode += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strCode += '</w2:columnInfo>';
    strCode += '<w2:data use="true"></w2:data>';
    strCode += '</w2:dataList>';
    $p.data.create(strCode);
    dlt_dept.setJSON(scwin.deptItems, false);

    // 바인딩 DataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowData, false);

    // LinkedDataList (dlt_bind 를 bind)
    let bindId = 'dlt_bind';
    if (cBindType === 'linkedDataList') {
        let strLinked = '';
        strLinked += '<w2:linkedDataList ' + strNameSpace + ' id="lnk_bind" bind="dlt_bind">';
        strLinked += '<w2:condition type="filter"></w2:condition>';
        strLinked += '<w2:condition type="sort"></w2:condition>';
        strLinked += '</w2:linkedDataList>';
        $p.data.create(strLinked);
        bindId = 'lnk_bind';
    }

    let strItems = '<w2:choices><w2:itemset nodeset="data:dlt_dept"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' sortable="true" sortEvent="onclick" dataList="data:' + bindId + '" checkAllType="false" id="" style="width:420px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column_name" value="이름" sortable="false"></w2:column>';
    strTarget += '<w2:column width="220" style="" inputType="text" id="column_dept" value="부서 (' + cInputType + ')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="name" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="220" style="" inputType="' + cInputType + '" sortLabel="true" selectedData="false" id="dept" value="">' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1 : GridView 에 바인딩된 DataList / LinkedDataList 의 sort() 로 부서 Column 오름차순 정렬
scwin.btn_sort_onclick = function (e) {
    scwin.getBindComp().sort("dept", 0);
}



// validation 1 : GridView 에 바인딩된 DataList / LinkedDataList 의 multisort() 로 부서 Column 오름차순 정렬
scwin.btn_multisort_onclick = function (e) {
    scwin.getBindComp().multisort({ "sortIndex" : "dept", "sortOrder" : "1" });
}



// validation 1, 2 판정 출력 : 정렬 상태(getSortableStatus) + 부서 표시 순서(Label) + 부서 Cell 값 순서
scwin.btn_checkSort_onclick = function (e) {
    let arrStatus = target1.getSortableStatus() || [];
    let strSort = (arrStatus.length === 0) ? "없음" : arrStatus.map(function (o) {
        return o.colID + " (" + (o.sortOrder == 1 ? "오름차순" : "내림차순") + ")";
    }).join(", ");

    let arrDisplay = [];
    let arrValue = [];
    for (let i = 0; i < target1.getRowCount(); i++) {
        arrDisplay.push(target1.getCellDisplayData(i, "dept"));
        arrValue.push(target1.getCellData(i, "dept"));
    }

    wf_body_bottom.getObj("scwin").setReturnValue("정렬 상태 : " + strSort + " / 표시 순서 : " + arrDisplay.join(", ") + " / Cell 값 순서 : " + arrValue.join(", "));
}
